import { useEffect, useMemo, useState } from "react";
import { ConditionLegend } from "./components/ConditionLegend";
import { MapView } from "./components/MapView";
import { PipeDetail } from "./components/PipeDetail";
import type { PipeCollection, PipeFeature } from "./types";

export default function App() {
  const [data, setData] = useState<PipeCollection | null>(null);
  const [error, setError] = useState<string | null>(null);
  const [selected, setSelected] = useState<PipeFeature | null>(null);

  // NFR-01: static file, no backend. Generated by scripts/generate-network.mjs
  useEffect(() => {
    fetch(`${import.meta.env.BASE_URL}network.geojson`)
      .then((r) => {
        if (!r.ok) throw new Error(`HTTP ${r.status}`);
        return r.json() as Promise<PipeCollection>;
      })
      .then(setData)
      .catch((e) => setError(`Could not load network.geojson (${e.message}). Run "npm run generate" first.`));
  }, []);

  const features = useMemo(() => data?.features ?? [], [data]);

  return (
    <div className="app">
      <header>
        <h1>Pipe network pilot</h1>
        <p>Fictional utility. Asset data is synthetic; streets &copy; OpenStreetMap contributors.</p>
      </header>
      <main>
        {error && <p className="error" role="alert">{error}</p>}
        {!data && !error && <p className="hint">Loading network&hellip;</p>}
        {data && <MapView data={data} selected={selected} onSelect={setSelected} />}
      </main>
      <aside>
        <p className="total">{features.length.toLocaleString("en")} pipe segments</p>
        <ConditionLegend features={features} />
        <PipeDetail feature={selected} />
      </aside>
    </div>
  );
}
